import{_ as r,C as o,c as a,o as s,aj as n,G as i,w as m}from"./chunks/framework.Bfdr4H5E.js";const u="/sk/images/Volume-at-Time.webp",p="/sk/images/Volume-Profile-01.webp",h="/sk/images/Volume-Profile-02.webp",c="/sk/images/Volume-Profile-03.webp",f="/sk/images/Volume-Profile-04.webp",d="/sk/images/Volume-Profile-05.webp",v="/sk/images/Volume-Profile-06.webp",g="/sk/images/Volume-Profile-07.webp",T=JSON.parse('{"title":"Volume Profile","description":"","frontmatter":{"outline":"deep","prev":{"text":"Price Action Strategies","link":"/trading-with-pav/price-action-strategies"},"next":{"text":"Different Volume Profile Shapes","link":"/trading-with-pav/different-volume-profile-shapes"}},"headers":[],"relativePath":"trading-with-pav/volume-profile.md","filePath":"trading-with-pav/volume-profile.md"}'),P={name:"trading-with-pav/volume-profile.md"};function w(V,e,b,_,k,y){const t=o("GraphComment"),l=o("ClientOnly");return s(),a("div",null,[e[0]||(e[0]=n('<h1 id="volume-profile" tabindex="-1">Volume Profile <a class="header-anchor" href="#volume-profile" aria-label="Permalink to &quot;Volume Profile&quot;">​</a></h1><p>Lets discover the most important tool in market i.e. Volume Profile.</p><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#volume-profile-1">Volume Profile</a></li><li><a href="#what-does-volume-profile-tell-us">What Does Volume Profile Tell Us?</a></li><li><a href="#volume-profile-point-of-control">Volume Profile: Point of control</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="volume-profile-1" tabindex="-1">Volume Profile <a class="header-anchor" href="#volume-profile-1" aria-label="Permalink to &quot;Volume Profile&quot;">​</a></h2><p><img src="'+u+'" alt="Volume-at-Time"></p><p>Volume at Time (Volume)</p><p>Unlike standard volume indicators that only show volumes at time, the Volume Profile can provide much more important information, which is volume at a specific price.</p><p><img src="'+p+'" alt="Volume-Profile-01"></p><p>Volume Profile</p><ul><li>Volume at price is so valuable because it tells us which price levels were most important for the big guys who dominate the markets.</li><li>The more volumes accumulate at a specific price level, the more significant the price level is.</li><li>You can tell the amount of volumes by the thickness of the Volume Profile.</li><li>In a place where the profile is wide, heavy volumes got accumulated. Where the Volume Profile is thin, only low volumes were traded.</li></ul><h2 id="what-does-volume-profile-tell-us" tabindex="-1">What Does Volume Profile Tell Us? <a class="header-anchor" href="#what-does-volume-profile-tell-us" aria-label="Permalink to &quot;What Does Volume Profile Tell Us?&quot;">​</a></h2><p><img src="'+h+'" alt="Volume-Profile-02"></p><p>Volume Profile to be applied from 07 Dec 22 10:55 am to 08 Dec 22 02:10 pm</p><p>Volume Profile tells us how the volume was distributed over a given price range. This is very useful information.</p><p><img src="'+c+'" alt="Volume-Profile-03"></p><p>Volume Profile Applied</p><p><img src="'+f+'" alt="Volume-Profile-04"></p><p>Volume Profile with Heavy and Low Volume Zone</p><p>In the picture above, you can see <strong>two heavy volume zones</strong> and One <strong>low volume zone</strong> where the Volume Profile is <strong>thin</strong>.</p><ul><li>What does the above particular picture tell us?</li><li>It tells us that <strong>big financial institutions</strong> were interested in trading in those <strong>two heavy-volume zones</strong>. On the other hand, they did not care for trading too much in the <strong>middle zone</strong> where the <strong>volumes</strong> were <strong>weak</strong>.</li></ul><p><img src="'+d+'" alt="Volume-Profile-05"></p><p>Volume Profile Read</p><ul><li>As above chart shows that this scenario could be a sign that big institutions were:</li><li>Building up their huge Long positions in the heavy volume zone (43000–43160).</li><li>Manipulating the price to go into a buy-off (that’s the thin profile).</li><li>And, finally, quitting their positions (or adding to them) in the heavy volume zone around (43320–43480).</li></ul><h2 id="volume-profile-point-of-control" tabindex="-1">Volume Profile: Point of control <a class="header-anchor" href="#volume-profile-point-of-control" aria-label="Permalink to &quot;Volume Profile: Point of control&quot;">​</a></h2><p><img src="'+v+'" alt="Volume-Profile-06"></p><p>Volume Profile: Point of Control aka POC (42228.40~42161.90)</p><ul><li>The most significant place in every Volume Profile histogram is the Point of control (POC).</li><li>POC is a place where the institutions traded most of their volumes, possibly a place where they were accumulating their big trading positions.</li><li>They accumulated their positions in a wider range, but POC is a place where they accumulated the most of their volumes.</li><li>It serves as a very strong reference point for all market participants because it shows where the interest of the institutions lies.</li></ul><p><img src="'+g+'" alt="Volume-Profile-07"></p><p>Volume Profile: Strong Reaction to POC</p><ul><li>Price usually makes quite strong reactions to POC levels.</li><li>However, in our trading, We don’t trade POCs blindly. We combine the information from Price Action with information that Volume Profile provides.</li><li>This combination gives us the perfect market overview that is needed for our analysis.</li><li>Apart from POC’s, we also look for other heavy volume areas. They work more or less the same way as POC‘s do.</li><li>The logic is the same: big volumes = big players.</li></ul><p>That’s it for this article in the next article we are going to explore various different shapes of volume profile.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',32)),i(l,null,{default:m(()=>[i(t)]),_:1})])}const x=r(P,[["render",w]]);export{T as __pageData,x as default};
